import{_ as t,o,c as a,aa as r}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/media/en/performedworks/diagram_vztahu2.png",m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction","wiki":"en:performedworks:start"},"headers":[],"relativePath":"en/performedworks/index.md","filePath":"en/performedworks/index.md","lastUpdated":1794388980000}'),n={name:"en/performedworks/index.md"};function s(l,e,d,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>The <strong>Performed Works</strong> module (hereinafter referred to as <strong>PW</strong>) is designed to create supporting documents for invoicing work carried out on a construction site. Each construction site has an itemized budget, where each item represents a specific type of work or material. Items contain basic information such as a textual description, quantity, unit of measurement, and unit price.</p><p>Performed works serve as the basis for interim invoicing and should document the current state of work progress on the construction site as of a specific date.</p><p>In practice, RCWs are most commonly prepared monthly. In very exceptional cases, a different time period may be used.</p><p>PWs are prepared at all levels of the contractor structure on a construction site. The highest level is between the main contractor (contractor) and the investor (client). Subcontractors also prepare PWs for the main contractor. This hierarchy may consist of an even greater number of levels.</p><h2 id="what-buildary-enables-and-what-its-advantage-is" tabindex="-1">What Buildary Enables and What Its Advantage Is <a class="header-anchor" href="#what-buildary-enables-and-what-its-advantage-is" aria-label="Permalink to &quot;What Buildary Enables and What Its Advantage Is&quot;">​</a></h2><p><strong>The aim of the Performed Works module is to cover the first two levels of contractor relationships, i.e. PWs between the contractor and the client, and between subcontractors and the contractor.</strong></p><img src="'+i+'" alt="" loading="lazy"><ul><li><p>Buildary therefore does not only address the highest-level contractor relationship, where only one Record of Completed Work is created each month. When used correctly, it also brings order and systematic processes to relationships with subcontractors, where dozens of records may be created each month, often in several versions. Buildary allows all participants to collaborate online using shared data, making communication easier and more transparent.</p></li><li><p>Buildary supports the entire process of preparing and modifying PWs through to their approval, across all contractor relationships.</p></li><li><p>The application provides clear entry, approval, and modification of PWs at the individual item level. The history of corrections is visible, and approval can be verified for each individual item.</p></li><li><p>The output of the process is a PDF file protected against changes by an electronic signature. The file contains all information about the completed work and includes metadata in its attributes that is useful when importing and checking the data in an ERP system.</p></li></ul><h3 id="buildary-enables" tabindex="-1">Buildary Enables: <a class="header-anchor" href="#buildary-enables" aria-label="Permalink to &quot;Buildary Enables:&quot;">​</a></h3><ul><li><p>Any number of clients, contractors, and subcontractors on a single construction site.</p></li><li><p>User permissions can be configured so that, although users work with shared data for a single construction site, each user sees only their own data and can perform only the operations they are authorized to perform.</p></li><li><p>The time period covered by the records can be set freely. It is configured by the construction site administrator and is shared by all participants. When integrating with other applications, however, it is advisable to respect any limitations resulting from the logic of those applications (e.g. in RSV, the period must not exceed one month).</p></li><li><p>Each participant creates their own <strong>Measurement Report (MR)</strong> for the given period. The report then progresses through individual statuses (<strong>Proposal, Approved, Changed, Rejected, Negotiated</strong>). The functions available to different users also depend on the current status of the MR.</p></li><li><p>Users are notified by e-mail of changes to the status of the Measurement Report.</p></li><li><p>Gradual approval of records of completed work at the individual item level. Each item quantity has its own status (<strong>Proposal, Approved, Changed, Rejected, Negotiated</strong>), so some items may already be approved while the correct quantity for others is still being negotiated.</p></li><li><p>Users have a continuous overview of the volume of completed work that has already been approved and the volume that is still undergoing the approval process.</p></li><li><p>The history of a given period can be viewed at any time, allowing users to see for each item what quantity was originally proposed for billing, how the proposal was modified, and what quantity was ultimately approved.</p></li></ul><h2 id="who-the-records-of-completed-work-module-is-intended-for" tabindex="-1">Who the Records of Completed Work Module Is Intended For <a class="header-anchor" href="#who-the-records-of-completed-work-module-is-intended-for" aria-label="Permalink to &quot;Who the Records of Completed Work Module Is Intended For&quot;">​</a></h2><ul><li><p>For investors who want to use a modern method of communication with contractors.</p></li><li><p>For contractors who want to gain control over their subcontractors&#39; performed work and, instead of dealing with a multitude of Excel files, have one reliable database accessible to all participants.</p></li><li><p>For anyone who wants to speed up, make more transparent, and better document the process of reporting and approving completed work on their construction sites.</p></li></ul>',13)])])}const f=t(n,[["render",s]]);export{m as __pageData,f as default};
